3) app-mount.jsx — register the three surfaces. `ctx.go` takes a nav id, my pages call go(pageKey, id), so map it:

  if(window.TahiSales){
    const salesGo = (go) => (to) => {
      const dest = { lead:'leads', leads:'leads', call:'calls', calls:'calls', deal:'deals', deals:'deals', client:'clients' }[to];
      if(dest && go) go(dest);
    };
    props.leadsContent = ctx => React.createElement(window.TahiSales.Leads, { ctx, go: salesGo(ctx.go) });
    props.callsContent = ctx => React.createElement(window.TahiSales.Calls, { ctx, go: salesGo(ctx.go) });
    props.dealsContent = ctx => React.createElement(window.TahiSales.Deals, { ctx, go: salesGo(ctx.go) });
  }

